/**
 * Unit tests for LocaleUtils.countriesByLanguage
 */
public class LocaleUtils_countriesByLanguage_TriageGen2Test {



    @Test
    public void testCountriesByLanguage_ValidLanguageCode() {
        // Tests the branch where languageCode is not null and exists in cache or needs calculation
        // We use a common language code like "en"
        String lang = "en";
        List result = LocaleUtils.countriesByLanguage(lang);

        assertNotNull("Result should not be null", result);
        // Verify that all returned locales have the correct language code
        for (Object obj : result) {
            Locale locale = (Locale) obj;
            assertEquals("Language code must match input", lang, locale.getLanguage());
            // The logic requires locale.getCountry().length() != 0
            assertFalse("Country code must not be empty", locale.getCountry().isEmpty());
            // The logic requires locale.getVariant().length() == 0
            assertEquals("Variant must be empty", "", locale.getVariant());
        }
    }






}

