    @Test
    public void testCountriesByLanguage_CacheEffectiveness() {
        // This test ensures that the logic flows through the cache path
        // By calling it twice, the second call hits the 'if (countries == null)' false path
        String lang = "fr";
        List firstCall = LocaleUtils.countriesByLanguage(lang);
        List secondCall = LocaleUtils.countriesByLanguage(lang);

        assertNotNull(firstCall);
        assertNotNull(secondCall);
        assertEquals("Second call should return same list instance or equal content", firstCall, secondCall);
