 */
public class LocaleUtils_countriesByLanguage_TriageGen2Test {









    @Test
    public void testCountriesByLanguage_UnmodifiableList() {
        // Tests if the returned list is unmodifiable when newly created
        String lang = "de";
        List result = LocaleUtils.countriesByLanguage(lang);

        if (!result.isEmpty()) {
            try {
                result.add(new Locale("unknown"));
                fail("Should have thrown UnsupportedOperationException");
            } catch (UnsupportedOperationException e) {
                // Success
            }
        }
    }
